// Inlines Leaflet + MarkerCluster into a TS module so the map works without a CDN.
const fs = require('fs');
const r = (p) => fs.readFileSync(require.resolve(p), 'utf8');
const out = `/* eslint-disable */
// Generated by scripts/gen-leaflet.js — do not edit.
export const LEAFLET_JS = ${JSON.stringify(r('leaflet/dist/leaflet.js'))};
export const LEAFLET_CSS = ${JSON.stringify(r('leaflet/dist/leaflet.css'))};
export const CLUSTER_JS = ${JSON.stringify(r('leaflet.markercluster/dist/leaflet.markercluster.js'))};
export const CLUSTER_CSS = ${JSON.stringify(r('leaflet.markercluster/dist/MarkerCluster.css'))};
`;
fs.writeFileSync('src/components/leafletAssets.ts', out);
console.log('leafletAssets.ts', out.length);
